sys_script_include.script:
var DocLocalExtractor = Class.create();
DocLocalExtractor.prototype = {
    initialize: function() {},

    // 添付レコードより全文テキスト取得
    extractText: function(attachGr) {
        var fileName = attachGr.file_name.toLowerCase();
        var fileBytes = new GlideSysAttachment().getBytes(attachGr);
        var text = "";

        if (fileName.endsWith(".pdf")) {
            text = this._readPdf(fileBytes);
        } else if (fileName.endsWith(".xlsx")) {
            text = this._readExcel(fileBytes);
        } else if (fileName.endsWith(".docx")) {
            text = this._readWord(fileBytes);
        } else {
            throw new Error("対応外ファイル：" + attachGr.file_name);
        }
        return text;
    },

    // PDFテキスト抽出
    _readPdf: function(bytes) {
        var pdfReader = new GlidePDFReader();
        pdfReader.setBytes(bytes);
        var fullText = "";
        while (pdfReader.nextPage()) {
            fullText += pdfReader.getPageText() + "\n";
        }
        pdfReader.close();
        return fullText;
    },

    // Excelテキスト抽出（全セル連結）
    _readExcel: function(bytes) {
        var excel = new GlideExcelParser();
        excel.setBytes(bytes);
        var fullText = "";
        while (excel.nextSheet()) {
            while (excel.nextRow()) {
                while (excel.nextCell()) {
                    fullText += excel.getCellValue() + " ";
                }
                fullText += "\n";
            }
        }
        excel.close();
        return fullText;
    },

    // Wordテキスト抽出
    _readWord: function(bytes) {
        var word = new GlideWordParser();
        word.setBytes(bytes);
        var fullText = word.getDocumentText();
        word.close();
        return fullText;
    },

    type: "DocLocalExtractor"
};
